#!/bin/sh
apk_menu(){ while :; do c=$(ui_menu APK 'Alpine package configuration.' repos 'Edit repositories' cache 'Configure persistent cache' world 'Edit world file' keys 'List trusted keys' audit 'Audit package database' fix 'Repair packages') || { _menu_rc=$?; [ "$_menu_rc" -eq "${UI_MENU_BACK_RC:-90}" ] && return 0; return "$_menu_rc"; }; case $c in repos) edit_file /etc/apk/repositories;; cache) p=$(ui_input 'APK cache' 'Cache directory:' /var/cache/apk) || continue; as_root mkdir -p "$p"; [ -e /etc/apk/cache ] || as_root ln -s "$p" /etc/apk/cache 2>/dev/null || true;; world) edit_file /etc/apk/world;; keys) ui_text Keys "$(ls -l /etc/apk/keys 2>/dev/null)";; audit) run_capture 'APK audit' apk audit;; fix) run_capture 'APK fix' as_root apk fix;; esac; done; }
